import type { APIRequestContext } from "@playwright/test";
import { expect, test, uniqueName } from "../../fixtures";

async function vendorInReview(member: APIRequestContext, prefix: string, expiry: string): Promise<string> {
  const name = uniqueName(prefix);
  const created = await member.post("/api/vendors", {
    data: { name, category: "software", contact_email: "ops@example.com" },
  });
  expect(created.status(), await created.text()).toBe(201);
  const { id } = (await created.json()) as { id: string };

  const documents: [string, string][] = [
    ["w9", `Legal Name: ${name}\nTax ID: 123456789\nBusiness Type: LLC\n`],
    [
      "insurance_certificate",
      `Insurer: Harbor Mutual\nPolicy Number: HM-1\nCoverage Amount: 2000000\nExpiry Date: ${expiry}\n`,
    ],
    ["contract", `Counterparty: Acme\nEffective Date: 2026-01-01\nExpiry Date: 2028-01-01\n`],
  ];
  for (const [kind, text] of documents) {
    const upload = await member.post(`/api/vendors/${id}/documents`, {
      multipart: { kind, file: { name: `${kind}.txt`, mimeType: "text/plain", buffer: Buffer.from(text) } },
    });
    expect(upload.status(), await upload.text()).toBe(201);
  }

  // Extraction runs in the background; wait until all three documents are extracted.
  await expect
    .poll(
      async () => {
        const res = await member.get(`/api/vendors/${id}/documents`);
        const docs = (await res.json()) as { status: string }[];
        return docs.length === 3 && docs.every((d) => d.status === "extracted");
      },
      { timeout: 15_000 },
    )
    .toBe(true);

  const submitted = await member.post(`/api/vendors/${id}/submit`);
  expect(submitted.status(), await submitted.text()).toBe(200);
  return id;
}

test("the review queue shows lowest confidence first", { tag: "@REV-03" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const shakyId = await vendorInReview(member, "Shaky Co", "next spring");
  const confidentId = await vendorInReview(member, "Confident Co", "2030-12-31");

  // Act
  const response = await reviewer.get("/api/review-queue");

  // Assert
  expect(response.status(), await response.text()).toBe(200);
  const queue = (await response.json()) as { vendor_id: string; lowest_confidence: number }[];
  const lowest = queue.map((item) => item.lowest_confidence);
  expect(lowest).toEqual([...lowest].sort((a, b) => a - b));
  const ids = queue.map((item) => item.vendor_id);
  expect(ids.indexOf(shakyId)).toBeGreaterThanOrEqual(0);
  expect(ids.indexOf(shakyId)).toBeLessThan(ids.indexOf(confidentId));
  expect(queue.find((item) => item.vendor_id === shakyId)?.lowest_confidence).toBe(0.4);
});
